import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"SSL Certificate FAQ","description":"","frontmatter":{"title":"SSL Certificate FAQ"},"headers":[],"relativePath":"operations-knowledge-base/ssl/ssl-certificate-faq.md","filePath":"operations-knowledge-base/ssl/ssl-certificate-faq.md","lastUpdated":1794309341000}'),r={name:"operations-knowledge-base/ssl/ssl-certificate-faq.md"};function n(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This article answers common questions about <strong>SSL certificate applications</strong> and <strong>Domain Control Validation (DCV)</strong>.</p><p>For step-by-step instructions, please refer to the <a href="/operations-knowledge-base/ssl/ssl-certificate-validation-methods-guide.html"><strong>SSL Certificate Validation Methods Guide</strong></a>.</p><hr><h2 id="_1-which-email-address-receives-the-validation-email" tabindex="-1">1. Which email address receives the validation email? <a class="header-anchor" href="#_1-which-email-address-receives-the-validation-email" aria-label="Permalink to &quot;1. Which email address receives the validation email?&quot;">​</a></h2><p>The validation email is sent to the <strong>DCV validation email address</strong>, not the order contact email.</p><p>The Certificate Authority (CA) sends the validation email to the DCV email address selected during the application process (such as <strong><a href="mailto:admin@yourdomain.com" target="_blank" rel="noreferrer">admin@yourdomain.com</a></strong> or <strong><a href="mailto:webmaster@yourdomain.com" target="_blank" rel="noreferrer">webmaster@yourdomain.com</a></strong>) or to the domain&#39;s <strong>WHOIS registrant email address</strong>.</p><p>Please ensure that the selected mailbox is active and able to receive emails.</p><hr><h2 id="_2-what-validation-methods-are-available-can-i-change-methods-during-validation" tabindex="-1">2. What validation methods are available? Can I change methods during validation? <a class="header-anchor" href="#_2-what-validation-methods-are-available-can-i-change-methods-during-validation" aria-label="Permalink to &quot;2. What validation methods are available? Can I change methods during validation?&quot;">​</a></h2><p>Three validation methods are supported. You only need to complete one of them, and you may switch between methods at any time during the validation process.</p><table tabindex="0"><thead><tr><th>Validation Method</th><th>Best For</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Email Validation</strong></td><td>Domain mailboxes that can receive emails</td><td>Supported addresses include <strong>admin@</strong>, <strong>administrator@</strong>, <strong>webmaster@</strong>, <strong>hostmaster@</strong>, <strong>postmaster@</strong>, or the <strong>WHOIS registrant email</strong></td></tr><tr><td><strong>DNS Validation</strong></td><td>You manage the domain&#39;s DNS</td><td>Add the DNS record provided by the system. Validation will complete after DNS propagation.</td></tr><tr><td><strong>HTTP File Validation</strong></td><td>You can upload files to your website&#39;s document root</td><td>Upload the validation file to <code>/.well-known/pki-validation/</code>. <strong>Wildcard certificates are not supported.</strong></td></tr></tbody></table><hr><h2 id="_3-how-long-does-it-take-to-receive-the-validation-email" tabindex="-1">3. How long does it take to receive the validation email? <a class="header-anchor" href="#_3-how-long-does-it-take-to-receive-the-validation-email" aria-label="Permalink to &quot;3. How long does it take to receive the validation email?&quot;">​</a></h2><p>The validation email is usually delivered <strong>within a few minutes</strong>.</p><p>If you have not received it after <strong>30 minutes</strong>, please check the following:</p><ul><li>Make sure you are checking the correct DCV validation mailbox.</li><li>Check your Spam, Junk, or Quarantine folders.</li><li>Confirm that the mailbox is active.</li><li>Verify that your domain&#39;s MX records are configured correctly.</li></ul><p>If you still do not receive the email, we recommend switching to <strong>DNS Validation</strong> or <strong>HTTP File Validation</strong>, or submitting a support ticket for assistance.</p><hr><h2 id="_4-will-incorrect-country-or-postal-code-information-affect-validation" tabindex="-1">4. Will incorrect country or postal code information affect validation? <a class="header-anchor" href="#_4-will-incorrect-country-or-postal-code-information-affect-validation" aria-label="Permalink to &quot;4. Will incorrect country or postal code information affect validation?&quot;">​</a></h2><p>No.</p><p>Domain Control Validation (DCV) only verifies that you have control over the domain. It is <strong>not affected</strong> by organization information such as the country or postal code.</p><p>However, we recommend providing accurate information for easier certificate management.</p><hr><h2 id="_5-http-file-validation-remains-unverified-what-should-i-check" tabindex="-1">5. HTTP File Validation remains unverified. What should I check? <a class="header-anchor" href="#_5-http-file-validation-remains-unverified-what-should-i-check" aria-label="Permalink to &quot;5. HTTP File Validation remains unverified. What should I check?&quot;">​</a></h2><h3 id="_1-each-domain-must-be-validated-separately" tabindex="-1">(1) Each domain must be validated separately <a class="header-anchor" href="#_1-each-domain-must-be-validated-separately" aria-label="Permalink to &quot;(1) Each domain must be validated separately&quot;">​</a></h3><p>If your certificate includes multiple domains (for example, <strong>example.com</strong> and <strong><a href="http://www.example.com/" target="_blank" rel="noreferrer">www.example.com</a></strong>), you must upload a validation file for each hostname.</p><p>For example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://example.com/.well-known/pki-validation/filename.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>http://www.example.com/.well-known/pki-validation/filename.txt</span></span></code></pre></div><hr><h3 id="_2-incorrect-file-path-or-file-content" tabindex="-1">(2) Incorrect file path or file content <a class="header-anchor" href="#_2-incorrect-file-path-or-file-content" aria-label="Permalink to &quot;(2) Incorrect file path or file content&quot;">​</a></h3><p>Please verify that:</p><ul><li>The validation file is located under:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/.well-known/pki-validation/</span></span></code></pre></div><ul><li>The file content exactly matches the content provided by the system.</li><li>The file is publicly accessible over HTTP and returns an <strong>HTTP 200 OK</strong> response.</li></ul><hr><h3 id="_3-cdn-or-reverse-proxy" tabindex="-1">(3) CDN or Reverse Proxy <a class="header-anchor" href="#_3-cdn-or-reverse-proxy" aria-label="Permalink to &quot;(3) CDN or Reverse Proxy&quot;">​</a></h3><p>If your website is behind a CDN or reverse proxy:</p><ul><li>Temporarily bypass or disable caching for the validation path.</li><li>Ensure that the Certificate Authority (CA) can access your origin server directly.</li></ul><hr><h2 id="_6-the-certificate-remains-in-pending-status-for-a-long-time" tabindex="-1">6. The certificate remains in <strong>Pending</strong> status for a long time <a class="header-anchor" href="#_6-the-certificate-remains-in-pending-status-for-a-long-time" aria-label="Permalink to &quot;6. The certificate remains in **Pending** status for a long time&quot;">​</a></h2><p>Please perform the following checks:</p><ul><li>Check your DCV status using the <strong>Sectigo Order Status Checker</strong>.</li><li>Switch to another validation method and save the changes, then switch back and save again to trigger a new validation check.</li><li>Confirm that your DNS records have fully propagated or that the validation file is publicly accessible.</li></ul><p>After the DCV process is completed, the certificate is typically issued <strong>within approximately 30 minutes</strong>.</p><p>If the certificate has still not been issued after that, please submit a support ticket and include your order number for further assistance.</p><hr><h2 id="_7-i-entered-incorrect-information-or-accidentally-clicked-cancel" tabindex="-1">7. I entered incorrect information or accidentally clicked <strong>Cancel</strong> <a class="header-anchor" href="#_7-i-entered-incorrect-information-or-accidentally-clicked-cancel" aria-label="Permalink to &quot;7. I entered incorrect information or accidentally clicked **Cancel**&quot;">​</a></h2><h3 id="pending" tabindex="-1">Pending <a class="header-anchor" href="#pending" aria-label="Permalink to &quot;Pending&quot;">​</a></h3><p>The domain usually cannot be modified while the certificate request is pending.</p><p>Please wait until the certificate is issued, or cancel the current order and submit a new application.</p><h3 id="issued" tabindex="-1">Issued <a class="header-anchor" href="#issued" aria-label="Permalink to &quot;Issued&quot;">​</a></h3><p>You can use the <strong>Replace</strong> function in the control panel to reissue the certificate with the correct domain.</p><h3 id="cancelled" tabindex="-1">Cancelled <a class="header-anchor" href="#cancelled" aria-label="Permalink to &quot;Cancelled&quot;">​</a></h3><p>Cancelled orders cannot be restored.</p><p>You will need to purchase the certificate again.</p><h2 id="_8-why-is-my-ssl-certificate-only-valid-for-199-days-instead-of-the-full-service-term" tabindex="-1">8: Why is my SSL certificate only valid for 199 days instead of the full service term? <a class="header-anchor" href="#_8-why-is-my-ssl-certificate-only-valid-for-199-days-instead-of-the-full-service-term" aria-label="Permalink to &quot;8: Why is my SSL certificate only valid for 199 days instead of the full service term?&quot;">​</a></h2><p>According to industry standards, the maximum validity period for a single SSL certificate issuance is <strong>199 days</strong>.</p><p>If you purchase an SSL certificate with a service term longer than 199 days, the system will first issue a certificate that is valid for <strong>199 days</strong>.</p><p>Within <strong>30 days before the certificate expires</strong>, the system will automatically reissue (renew) a new certificate to cover the remaining service period.</p><p><strong>Please note:</strong> After the certificate is reissued, you will need to <strong>download and redeploy the new certificate</strong> on your server. The new certificate will <strong>not</strong> be deployed automatically.</p><h2 id="_9-do-i-need-to-redeploy-the-certificate-after-it-is-automatically-reissued" tabindex="-1">9. Do I need to redeploy the certificate after it is automatically reissued? <a class="header-anchor" href="#_9-do-i-need-to-redeploy-the-certificate-after-it-is-automatically-reissued" aria-label="Permalink to &quot;9. Do I need to redeploy the certificate after it is automatically reissued?&quot;">​</a></h2><p>Yes.</p><p>Automatic certificate reissuance only generates a new certificate. It <strong>does not</strong> automatically deploy the new certificate to your server.</p><p>After the certificate has been reissued, please download the latest certificate and redeploy it to your server or web service to ensure your website continues to use HTTPS properly and to prevent service interruptions caused by an expired certificate.</p><hr><h2 id="_10-technical-support" tabindex="-1">10. Technical Support <a class="header-anchor" href="#_10-technical-support" aria-label="Permalink to &quot;10. Technical Support&quot;">​</a></h2><p>If you need further assistance, please submit a support ticket through the Client Area and include the following information:</p><ul><li>Your SSL order number or domain name</li><li>The validation method currently in use</li><li>The troubleshooting steps you have already performed</li><li>Any relevant error messages or screenshots</li></ul><p>Providing this information will help us investigate and resolve your issue more efficiently.</p>`,69)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
